  /**
   * Attempts to open a Sourcegraph file URL as a local file in VS Code.
   * Fails if the URI is not a valid Sourcegraph URL for a file or if the
   * file does not belong to the current workspace.
   */
  async openSourcegraphUriAsLocalFile(uri) {
    const match3 = uri.path.match(
      /^\/*(?<repoName>[^@]*)(?<revision>@.*)?\/-\/blob\/(?<filePath>.*)$/
    );
    if (!match3 || !match3.groups) {
      throw new Error("failed to extract repo name and file path");
    }
    const { repoName, filePath } = match3.groups;
    const workspaceFolder = await workspaceFolderForRepo(repoName);
    if (!workspaceFolder) {
      throw new Error("could not find workspace for repo");
    }
    const lineParam = this.extractLineParamFromURI(uri);
    const selectionStart = this.lineParamToRange(lineParam).start;
    const selection = new vscode114.Range(selectionStart, selectionStart);
    const fileUri = workspaceFolder.uri.with({
      path: `${workspaceFolder.uri.path}/${filePath}`
    });
    const document2 = await vscode114.workspace.openTextDocument(fileUri);
    await vscode114.window.showTextDocument(document2, {
      selection,
      preview: true
    });
  }
  extractLineParamFromURI(uri) {
    return uri.query.split("&").find((key2) => key2.match(/^L\d+(?:-\d+)?$/));
  }
  lineParamToRange(lineParam) {
    const lines2 = (lineParam ?? "0").replace("L", "").split("-").map((num) => Number.parseInt(num));
    return new vscode114.Range(lines2.at(0) || 0, 0, lines2.at(1) || (lines2.at(0) || 0) + 20, 0);
  }
