  async reevaluateSearchWithSelectedFilters({
    index,
    selectedFilters
  }) {
    if (index === void 0 || !Array.isArray(selectedFilters)) {
      return;
    }
    this.handleAbort();
    const humanMessage = this.chatBuilder.getMessages().at(index);
    const assistantMessage = this.chatBuilder.getMessages().at(index + 1);
    if (humanMessage?.speaker !== "human" || humanMessage.intent !== "search" || assistantMessage?.speaker !== "assistant" || !assistantMessage?.search?.query) {
      return;
    }
    this.chatBuilder.updateAssistantMessageAtIndex(index + 1, {
      ...assistantMessage,
      search: {
        ...assistantMessage.search,
        selectedFilters
      },
      text: void 0
    });
    this.postViewTranscript();
    try {
      const query = this.appendSelectedFiltersToSearchQuery({
        query: assistantMessage.search.query,
        filters: selectedFilters
      });
      const response = await graphqlClient.nlsSearchQuery({ query });
      this.chatBuilder.updateAssistantMessageAtIndex(index + 1, {
        ...assistantMessage,
        error: void 0,
        search: {
          ...assistantMessage.search,
          queryWithSelectedFilters: query,
          response,
          selectedFilters
        },
        text: ps`search found ${response?.results.results.length || 0} results`
      });
    } catch (err2) {
      this.chatBuilder.addErrorAsBotMessage(err2, ChatBuilder.NO_MODEL);
    } finally {
      void this.saveSession();
      this.postViewTranscript();
    }
  }
  appendSelectedFiltersToSearchQuery({
    query,
    filters
  }) {
    if (!filters.length) {
      return query;
    }
    const repoFilters = filters.filter((filter4) => filter4.kind === "repo");
    const repoFilter = repoFilters.length ? `repo:^(${repoFilters.map((filter4) => filter4.value.replace("repo:^", "").replace(/\$$/, "")).join("|")})$` : "";
    let count = 50;
    switch (filters.find((filter4) => filter4.kind === "type")?.value) {
      case "type:path":
      case "type:repo":
        count = 20;
        break;
    }
    return `${query} ${filters.filter((f) => f.kind !== "repo").map((f) => f.value).join(" ")} ${repoFilter} count:${count}`;
  }
